        WAIT:
        begin
            counter <= counter + 1;
            if (counter == THRESHOLD)
                state <= PROCESS;
        end

        PROCESS:
        begin
            state <= DONE;
        end

        DONE:
        begin
            state <= IDLE;
        end

        default:
            state <= IDLE;
    endcase
end

assign out = (state == DONE);

